import {RelativeTime, Stack, StateLabel} from '@primer/react'

import {AlertStatusLabels, StateLabelStatusMap} from './consts'
import {TrackingIssue} from './TrackingIssue'
import type {AlertPageHeaderDetailsProps} from './types'

const Separator = () => <span> • </span>

export const AlertPageHeaderDetails = ({
  subtitle,
  status,
  timestamp,
  trailingMessage,
  trackingIssue,
}: AlertPageHeaderDetailsProps) => {
  if (!status && !subtitle && !trailingMessage && !timestamp && !trackingIssue) return null

  return (
    <Stack align="center" direction="horizontal" gap="condensed">
      {status && <StateLabel status={StateLabelStatusMap[status]}>{AlertStatusLabels[status]}</StateLabel>}

      {trackingIssue && <TrackingIssue {...trackingIssue} />}

      {subtitle || timestamp || trailingMessage ? (
        <span className="fgColor-muted lh-condensed">
          {subtitle}
          {subtitle && timestamp ? <Separator /> : null}
          {timestamp && <RelativeTime date={timestamp} prefix="" />}
          {(subtitle || timestamp) && trailingMessage ? <Separator /> : null}
          {trailingMessage}
        </span>
      ) : null}
    </Stack>
  )
}
